CREATE TYPE "EstadoObra" AS ENUM ('ACTIVA','PAUSADA','FINALIZADA');
CREATE TYPE "EstadoDocumento" AS ENUM ('VIGENTE','PENDIENTE','VENCIDO','ARCHIVADO');
CREATE TABLE "TBL_OBRAS" ("id_obras" SERIAL PRIMARY KEY,"nombre_obra" VARCHAR(200) NOT NULL,"direccion" VARCHAR(200),"numero_expediente" VARCHAR(100) UNIQUE,"promotor" VARCHAR(200),"empresa_constructura" VARCHAR(200),"direccion_facultativa" VARCHAR(200),"estado" "EstadoObra" NOT NULL DEFAULT 'ACTIVA');
CREATE TABLE "TBL_PERSONAS" ("id_persona" SERIAL PRIMARY KEY,"documento" VARCHAR(50) UNIQUE,"nombres" VARCHAR(100) NOT NULL,"apellidos" VARCHAR(100) NOT NULL,"email" VARCHAR(100) UNIQUE,"telefono" VARCHAR(30));
CREATE TABLE "TBL_USUARIOS" ("id" SERIAL PRIMARY KEY,"id_persona" INTEGER UNIQUE NOT NULL REFERENCES "TBL_PERSONAS"("id_persona") ON DELETE CASCADE,"email" VARCHAR(100) UNIQUE NOT NULL,"password_hash" TEXT NOT NULL,"activo" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TBL_ROLES_SISTEMAS" ("id_rol" SERIAL PRIMARY KEY,"nombre_rol" VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE "TBL_OCUPACION" ("id_ocupacion" SERIAL PRIMARY KEY,"nombre_ocupacion" VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE "TBL_EMPRESAS" ("id_empresa" SERIAL PRIMARY KEY,"nit_rut" VARCHAR(50) UNIQUE NOT NULL,"razon_social" VARCHAR(200) NOT NULL);
CREATE TABLE "TBL_EQUIPOS_MAQUINARIA" ("id_equipos_maquinaria" SERIAL PRIMARY KEY,"descripcion" VARCHAR(200) NOT NULL,"tipo_modelo" VARCHAR(100));
CREATE TABLE "TBL_CATEGORIA_DOCUMENTO" ("id_categoria_documento" SERIAL PRIMARY KEY,"nombre_categoria" VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE "TBL_PERSONA_ROL" ("id_persona" INTEGER REFERENCES "TBL_PERSONAS"("id_persona") ON DELETE CASCADE,"id_rol" INTEGER REFERENCES "TBL_ROLES_SISTEMAS"("id_rol") ON DELETE CASCADE,PRIMARY KEY("id_persona","id_rol"));
CREATE TABLE "TBL_PERSONA_EMPRESA" ("id_persona" INTEGER REFERENCES "TBL_PERSONAS"("id_persona") ON DELETE CASCADE,"id_empresa" INTEGER REFERENCES "TBL_EMPRESAS"("id_empresa") ON DELETE CASCADE,"fecha_inicio" DATE,"fecha_fin" DATE,PRIMARY KEY("id_persona","id_empresa"));
CREATE TABLE "TBL_PERSONA_OCUPACION" ("id_persona" INTEGER REFERENCES "TBL_PERSONAS"("id_persona") ON DELETE CASCADE,"id_ocupacion" INTEGER REFERENCES "TBL_OCUPACION"("id_ocupacion") ON DELETE CASCADE,PRIMARY KEY("id_persona","id_ocupacion"));
CREATE TABLE "TBL_ASIGNACION_OBRA" ("id_asignacion" SERIAL PRIMARY KEY,"id_obras" INTEGER NOT NULL REFERENCES "TBL_OBRAS"("id_obras") ON DELETE CASCADE,"id_persona" INTEGER NOT NULL REFERENCES "TBL_PERSONAS"("id_persona") ON DELETE CASCADE,"id_rol" INTEGER NOT NULL REFERENCES "TBL_ROLES_SISTEMAS"("id_rol"),"id_empresa" INTEGER REFERENCES "TBL_EMPRESAS"("id_empresa"),UNIQUE("id_obras","id_persona","id_rol"));
CREATE TABLE "TBL_ARCHIVO_DOCUMENTAL" ("id_documento" SERIAL PRIMARY KEY,"id_obras" INTEGER NOT NULL REFERENCES "TBL_OBRAS"("id_obras"),"id_categoria_documento" INTEGER NOT NULL REFERENCES "TBL_CATEGORIA_DOCUMENTO"("id_categoria_documento"),"id_responsable" INTEGER NOT NULL REFERENCES "TBL_PERSONAS"("id_persona"),"nombre_original" TEXT NOT NULL,"ruta" TEXT UNIQUE NOT NULL,"formato" VARCHAR(50) NOT NULL,"tamano" INTEGER NOT NULL,"estado" "EstadoDocumento" NOT NULL DEFAULT 'VIGENTE',"fecha_registro" DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE "TBL_PARTE_DIARIO" ("id_parte" SERIAL PRIMARY KEY,"id_obras" INTEGER NOT NULL REFERENCES "TBL_OBRAS"("id_obras"),"fecha" DATE NOT NULL,"id_redactor" INTEGER NOT NULL REFERENCES "TBL_PERSONAS"("id_persona"),"hora_entrada" TIME,"hora_salida" TIME,"firma_redactor" BOOLEAN NOT NULL DEFAULT false,"firma_dir_facultativa" BOOLEAN NOT NULL DEFAULT false,UNIQUE("id_obras","fecha"));
CREATE TABLE "TBL_CLIMA_JORNADA" ("id_clima" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"franja_horaria" VARCHAR(50) NOT NULL,"condicion" VARCHAR(100) NOT NULL,"temperatura" DECIMAL(5,2),"precipitacion" VARCHAR(100),"viento_mph" DECIMAL(5,2));
CREATE TABLE "TBL_PLANTILLA_ASISTENCIA" ("id_asistencia" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"id_empresa" INTEGER NOT NULL REFERENCES "TBL_EMPRESAS"("id_empresa"),"id_ocupacion" INTEGER NOT NULL REFERENCES "TBL_OCUPACION"("id_ocupacion"),"num_trabajadores" INTEGER NOT NULL,"horas_totales" DECIMAL(7,2) NOT NULL);
CREATE TABLE "TBL_USO_MAQUINARIA" ("id_uso_maquinaria" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"id_equipos_maquinaria" INTEGER NOT NULL REFERENCES "TBL_EQUIPOS_MAQUINARIA"("id_equipos_maquinaria"),"estado_operativo" VARCHAR(100) NOT NULL);
CREATE TABLE "TBL_TAREAS_EJECUTADAS" ("id_tarea" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"zona_eje" VARCHAR(100) NOT NULL,"descripcion" TEXT NOT NULL,"avance" VARCHAR(50) NOT NULL,"trabajo_extra" BOOLEAN NOT NULL DEFAULT false,"autorizado" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "TBL_INCIDENCIAS_HSE" ("id_incidencia" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"tipo" VARCHAR(100) NOT NULL,"hora" TIME,"descripcion_detallada" TEXT NOT NULL);
CREATE TABLE "TBL_SUMINISTROS_RECEPCION" ("id_suministro" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"id_empresa" INTEGER NOT NULL REFERENCES "TBL_EMPRESAS"("id_empresa"),"descripcion_material" VARCHAR(200) NOT NULL,"num_albaran" VARCHAR(100),"conforme" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "TBL_OBSERVACIONES_VISITAS" ("id_observacion" SERIAL PRIMARY KEY,"id_parte" INTEGER NOT NULL REFERENCES "TBL_PARTE_DIARIO"("id_parte") ON DELETE CASCADE,"tipo_registro" VARCHAR(100) NOT NULL,"responsable_asignado" VARCHAR(150),"plazo" DATE,"descripcion" TEXT NOT NULL);
CREATE INDEX "parte_fecha_idx" ON "TBL_PARTE_DIARIO"("fecha");
